const missions=[
{title:['The takeaway warm-up','포장 주문 시작하기'],short:['Takeaway','포장 주문'],goal:['Take away 1 gimbap and 1 portion of fried dumplings. Choose two non-spicy dishes.','김밥 1개와 군만두 1인분을 포장하세요. 맵지 않은 두 가지 음식을 골라 보세요.'],mode:'takeaway',items:{gimbap:1,mandu:1},hint:['포장 means takeaway. 김밥 and 군만두 are the two dishes you need.','포장을 선택하고 김밥과 군만두를 하나씩 담으세요.'],phrase:['김밥 하나랑 군만두 하나 포장해 주세요.','One gimbap and one portion of fried dumplings to go, please.']},
{title:['A little less heat','맵기는 조금 순하게'],short:['Mild + cheese','순한맛·치즈'],goal:['Eat in. Order 1 tteokbokki, choose mild, and add cheese as an extra.','매장에서 먹을 떡볶이 1개를 주문하세요. 순한맛을 선택하고 치즈를 추가하세요.'],mode:'dine',items:{tteok:1},spice:'mild',extra:true,hint:['Pick 떡볶이, then 순한맛 (mild) and 치즈 추가 (extra cheese).','떡볶이를 고른 다음 순한맛과 치즈 추가를 선택하세요.'],phrase:['떡볶이 순한맛에 치즈 추가해 주세요.','Mild tteokbokki with extra cheese, please.']},
{title:['Lunch for two','둘이 먹는 점심'],short:['For two','두 사람'],goal:['Eat in. Order 2 regular-spice ramyeon and 1 portion of dumplings. Keep the total under ₩12,000.','매장에서 먹을 보통맛 라면 2개와 군만두 1인분을 주문하세요. 총액은 12,000원 미만이에요.'],mode:'dine',items:{ramen:2,mandu:1},spice:'normal',budget:12000,hint:['수량 is quantity. Increase 라면 to 2; 군만두 stays at 1.','라면 수량을 2로 올리고 군만두는 1로 두세요.'],phrase:['라면 두 개랑 군만두 하나 주세요.','Two ramyeon and one portion of fried dumplings, please.']},
{title:['Catch the wrong item','잘못 담은 메뉴 찾기'],short:['Fix the basket','주문 수정'],goal:['Your basket has a mistake. Remove the tteokbokki. Take away 1 gimbap and 1 fish cake soup instead.','장바구니에 잘못 담긴 메뉴가 있어요. 떡볶이를 빼고 김밥 1개와 어묵탕 1개를 포장하세요.'],mode:'takeaway',items:{gimbap:1,soup:1},seed:'tteok',hint:['삭제 removes an item. Replace 떡볶이 with 어묵탕, then check 포장.','삭제로 떡볶이를 빼고 어묵탕을 추가한 다음 포장을 확인하세요.'],phrase:['떡볶이 빼고 어묵탕으로 바꿔 주세요.','Please replace the tteokbokki with fish cake soup.']},
{title:['You’re ready to order','이제 직접 주문해요'],short:['On your own','혼자 주문'],goal:['Eat in. Get 1 fish cake soup and 1 portion of dumplings, with no extras. Spend less than ₩9,000.','매장에서 어묵탕 1개와 군만두 1인분을 먹으려고 해요. 추가 옵션 없이 9,000원 미만으로 주문하세요.'],mode:'dine',items:{soup:1,mandu:1},budget:9000,hint:['Read 어묵탕 and 군만두 on the menu. Check 매장 before confirming.','메뉴판에서 어묵탕과 군만두를 찾아 매장 주문으로 확인하세요.'],phrase:['어묵탕 하나랑 군만두 하나 주세요.','One fish cake soup and one portion of fried dumplings, please.']}
];
const strings={play:['Practice','주문 연습'],guides:['Travel guides','여행 가이드'],about:['About','소개'],eyebrow:['A LITTLE PRACTICE. A BETTER TRIP.','작은 연습으로 더 편안한 여행.'],headline:['Your first Korean order.','한국에서의 첫 주문.'],intro:['Read a Korean menu and rehearse your order before your trip.','여행 전에 메뉴를 읽고 직접 골라 보세요. 실수해도 괜찮아요.'],stamp:['Try it here.<br>Order it there.','여기서 연습하고<br>한국에서 주문해요.'],time:['5 missions · about 2 min each','미션 5개 · 한 번에 약 2분'],practiceTag:['PRACTICE, NOT A REAL ORDER','실제 주문이 아닌 연습이에요'],restaurant:['Your neighborhood snack shop','가상의 동네 분식집'],fictional:['Fictional restaurant','가상 식당'],mode:['Where are you eating?','어디서 드시나요?'],dine:['Dine in','매장에서 먹기'],takeaway:['Takeaway','가져가기'],menu:['메뉴 · The menu','메뉴 · 골라 보세요'],menuHint:['Tap a dish to choose options','메뉴를 눌러 옵션을 고르세요'],menuNote:['Prices and recipes are invented for practice. “Not spicy” does not mean allergen-free.','연습용 가격과 조리법이에요. 맵지 않아도 알레르기 유발 성분이 있을 수 있어요.'],yourOrder:['Your order','내 주문'],total:['Total','합계'],review:['Review order','주문 확인하기'],noPayment:['Just practice. No payment, ever.','연습만 해요. 실제 결제는 없어요.'],hint:['A little help?','힌트가 필요해요'],beyond:['BEYOND THE PRACTICE MENU','여행에 도움이 되는 작은 정보'],learn:['A few words go a long way.','몇 가지 표현으로 더 편안하게.'],allGuides:['Explore the travel guides','여행 가이드 읽기'],footer:['A small rehearsal for your next Korean adventure.','다음 한국 여행을 위한 작은 리허설.']};
Object.assign(strings,{guide1tag:['01 / KIOSKS','01 / 키오스크'],guide1title:['From the first tap<br>to the final screen.','첫 터치부터<br>마지막 확인까지.'],guide1desc:['Understand the Korean kiosk ordering flow.','한국 키오스크의 주문 흐름을 알아봐요.'],guide2tag:['02 / THE TWO BUTTONS','02 / 두 가지 버튼'],guide2title:['매장 or 포장?<br>You’ve got this.','매장과 포장,<br>이제 헷갈리지 않아요.'],guide2desc:['Know which button means eating here or taking away.','매장에서 먹기와 가져가기의 차이를 익혀요.'],guide3tag:['03 / MENU WORDS','03 / 메뉴판 읽기'],guide3title:['Less guessing.<br>More good food.','더 잘 읽고,<br>더 맛있게 먹어요.'],guide3desc:['Read dish names, quantities, and options.','메뉴 이름, 수량과 옵션을 읽어봐요.'],contact:['About & contact','소개·문의'],privacy:['Privacy','개인정보 안내'],terms:['Terms','이용 안내']});
const $=id=>document.getElementById(id);const lang=0;let mission=0,mode='dine',cart=[],completed=new Set(),uid=0;
try{const saved=JSON.parse(localStorage.getItem('menunori-completed')||'[]');completed=new Set(Array.isArray(saved)?saved.filter(x=>Number.isInteger(x)&&x>=0&&x<5):[])}catch{}
const t=(en,ko)=>lang?ko:en;const money=n=>'₩'+n.toLocaleString('en-US');const itemPrice=x=>menu.find(f=>f.id===x.id).price+(x.extra?1000:0);const total=()=>cart.reduce((s,x)=>s+itemPrice(x)*x.qty,0);const name=f=>lang?f.ko:f.en;const opts=x=>[x.spice?t(x.spice==='mild'?'Mild':'Regular spice',x.spice==='mild'?'순한맛':'보통맛'):null,x.extra?t('Extra cheese','치즈 추가'):null].filter(Boolean).join(' · ');
function render(){document.documentElement.lang=lang?'ko':'en';document.querySelectorAll('[data-i18n]').forEach(e=>{e.innerHTML=strings[e.dataset.i18n][lang]});$('mission-title').textContent=`0${mission+1} / ${missions[mission].title[lang]}`;$('mission-goal').textContent=missions[mission].goal[lang];$('progress-text').textContent=t(`${completed.size}/5 completed`,`${completed.size}/5 완료`);$('progress-dots').innerHTML=missions.map((_,i)=>`<span class="dot ${completed.has(i)?'done':''}" aria-hidden="true"></span>`).join('');$('mission-tabs').innerHTML=missions.map((m,i)=>`<button data-mission="${i}" class="${i===mission?'selected':''}" aria-pressed="${i===mission}">${completed.has(i)?'✓ ':''}${i+1}. ${m.short[lang]}</button>`).join('');$('hint-text').textContent=missions[mission].hint[lang];$('menu-grid').innerHTML=menu.map(f=>`<button class="food-card" data-food="${f.id}" aria-label="${t('Choose','선택')}: ${f.ko} · ${f.en}, ${money(f.price)}"><span class="food-tag">${f.tag[lang]}</span><div class="food-art" aria-hidden="true">${f.emoji}</div><div class="food-info"><h3>${f.ko}</h3><p>${f.en}</p><div class="food-info-bottom"><span>${money(f.price)}</span><span class="plus" aria-hidden="true">+</span></div></div></button>`).join('');renderCart()}
function renderCart(){$('dine').setAttribute('aria-pressed',mode==='dine');$('takeaway').setAttribute('aria-pressed',mode==='takeaway');$('cart-mode').textContent=mode==='dine'?t('매장 · Eating here','매장 · 매장에서 먹어요'):t('포장 · Taking away','포장 · 가져가요');$('cart-count').textContent=cart.reduce((s,x)=>s+x.qty,0);$('cart-items').innerHTML=cart.length?cart.map(x=>{const f=menu.find(y=>y.id===x.id);return `<div class="cart-item"><div class="cart-item-title"><span>${name(f)}</span><span>${money(itemPrice(x)*x.qty)}</span></div><small>${f.ko}${opts(x)?' · '+opts(x):''}</small><div class="qty-line"><button data-qty="${x.key}" data-change="-1" aria-label="${t('Decrease','수량 줄이기')} ${name(f)}">−</button><span>${x.qty}</span><button data-qty="${x.key}" data-change="1" aria-label="${t('Increase','수량 늘리기')} ${name(f)}" ${x.qty>=9?'disabled':''}>+</button><button class="remove" data-remove="${x.key}">${t('Remove','삭제')}</button></div></div>`}).join(''):`<div class="empty-cart"><span class="empty-icon" aria-hidden="true">▤</span>${t('Good food starts here.','맛있는 주문을 시작해요.')}<small>${t('Choose a dish from the menu.','메뉴판에서 음식을 골라 주세요.')}</small></div>`;$('total').textContent=money(total());$('review').disabled=!cart.length}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2200)}
function startMission(i){if(!Number.isInteger(i)||i<0||i>=5)throw Error('Invalid mission');mission=i;mode='dine';cart=[];if(missions[i].seed){cart=[{key:++uid,id:'tteok',qty:1,spice:'normal',extra:false}]}render()}
function addItem(id,qty=1,spice='normal',extra=false){const f=menu.find(x=>x.id===id);if(!f||!Number.isInteger(qty)||qty<1||qty>9||!['normal','mild'].includes(spice)||typeof extra!=='boolean'||(extra&&!f.cheese))throw Error('Invalid menu options');const sp=f.spice?spice:null;const existing=cart.find(x=>x.id===id&&x.spice===sp&&x.extra===extra);if(existing){if(existing.qty+qty>9)throw Error(t('Maximum 9 per item.','메뉴별 최대 수량은 9개예요.'));existing.qty+=qty}else{cart.push({key:++uid,id,qty,spice:sp,extra})}renderCart();toast(t(`${f.en} added`,`${f.ko} 담았어요`))}
function showFood(id){const f=menu.find(x=>x.id===id);$('food-dialog').innerHTML=`<button class="close" data-close aria-label="${t('Close','닫기')}">×</button><p class="eyebrow">${f.roman}</p><h2 id="food-title">${f.ko} · ${f.en}</h2><p>${f.desc[lang]}</p><div class="dialog-art" style="background-position:${[0,50,100][menu.indexOf(f)%3]}% ${menu.indexOf(f)>2?100:0}%" aria-hidden="true"></div><form id="food-form">${f.spice?`<fieldset><legend>${t('맵기 · Spice level','맵기')}</legend><div class="option-list"><label><input type="radio" name="spice" value="normal" checked>${t('보통맛 · Regular','보통맛')}</label><label><input type="radio" name="spice" value="mild">${t('순한맛 · Mild','순한맛')}</label></div></fieldset>`:''}${f.cheese?`<fieldset><legend>${t('추가 · Extras','추가 옵션')}</legend><div class="option-list"><label><input type="checkbox" name="extra">${t('치즈 추가 · Cheese','치즈 추가')} +₩1,000</label></div></fieldset>`:''}<fieldset><legend>${t('수량 · Quantity','수량')}</legend><div class="qty-control"><button type="button" id="food-minus" aria-label="${t('Decrease quantity','수량 줄이기')}">−</button><output id="food-quantity">1</output><button type="button" id="food-plus" aria-label="${t('Increase quantity','수량 늘리기')}">+</button></div></fieldset><div class="dialog-actions"><button class="primary" type="submit">${t('Add to order','주문에 담기')} · <span id="food-price">${money(f.price)}</span></button></div></form>`;let qty=1;const price=()=>{$('food-quantity').textContent=qty;$('food-price').textContent=money((f.price+($('food-form').elements.extra?.checked?1000:0))*qty);$('food-minus').disabled=qty===1;$('food-plus').disabled=qty===9};$('food-minus').onclick=()=>{qty=Math.max(1,qty-1);price()};$('food-plus').onclick=()=>{qty=Math.min(9,qty+1);price()};$('food-form').onchange=price;$('food-form').onsubmit=e=>{e.preventDefault();try{addItem(id,qty,$('food-form').elements.spice?.value||'normal',!!$('food-form').elements.extra?.checked);$('food-dialog').close()}catch(err){toast(err.message)}};price();$('food-dialog').showModal()}
function receipt(){return `<div class="receipt"><div class="receipt-line"><strong>${t('Order type','주문 방식')}</strong><span>${mode==='dine'?t('매장 · Dine in','매장'):t('포장 · Takeaway','포장')}</span></div>${cart.map(x=>{const f=menu.find(y=>y.id===x.id);return `<div class="receipt-line"><span>${f.ko} × ${x.qty}<small>${f.en}${opts(x)?' · '+opts(x):''}</small></span><span>${money(itemPrice(x)*x.qty)}</span></div>`}).join('')}<div class="receipt-line"><strong>${t('Total','합계')}</strong><strong>${money(total())}</strong></div></div>`}
function review(){$('review-dialog').innerHTML=`<button class="close" data-close aria-label="${t('Close','닫기')}">×</button><p class="eyebrow">${t('ONE LAST LOOK','마지막으로 확인해요')}</p><h2 id="review-title">${t('Does everything look right?','주문이 맞나요?')}</h2><p>${t('Check the dishes, quantities, options and total before placing your practice order.','메뉴, 수량, 옵션과 총액을 확인한 뒤 연습 주문을 완료하세요.')}</p>${receipt()}<div class="dialog-actions"><button class="secondary" data-close>${t('Keep editing','다시 수정')}</button><button class="primary" id="confirm">${t('Place practice order','연습 주문 완료')}</button></div><p>${t('No payment details are collected.','결제 정보를 받지 않아요.')}</p>`;$('confirm').onclick=finish;$('review-dialog').showModal()}
function evaluate(){const m=missions[mission];const counts=Object.fromEntries(menu.map(f=>[f.id,cart.filter(x=>x.id===f.id).reduce((s,x)=>s+x.qty,0)]));const exact=menu.every(f=>counts[f.id]===(m.items[f.id]||0));const checks=[{ok:mode===m.mode,text:t(`Order type: ${m.mode==='dine'?'dine in (매장)':'takeaway (포장)'}`,`주문 방식: ${m.mode==='dine'?'매장':'포장'}`)},{ok:exact,text:t('Dishes: ','메뉴: ')+Object.entries(m.items).map(([id,n])=>name(menu.find(f=>f.id===id))+' × '+n).join(' + ')}];const optionOK=cart.every(x=>(!m.spice||!x.spice||x.spice===m.spice)&&x.extra===!!(m.extra&&x.id==='tteok'));checks.push({ok:optionOK,text:m.spice?t(`Spice: ${m.spice==='mild'?'mild':'regular'}${m.extra?' + extra cheese':''}`,`맵기: ${m.spice==='mild'?'순한맛':'보통맛'}${m.extra?' + 치즈 추가':''}`):t('No extra options','추가 옵션 없음')});if(m.budget)checks.push({ok:total()<m.budget,text:t(`Total below ${money(m.budget)} (yours: ${money(total())})`,`총액 ${money(m.budget)} 미만 (내 주문: ${money(total())})`)});return checks}
function finish(){const checks=evaluate(),pass=checks.every(x=>x.ok);$('review-dialog').close();if(pass){completed.add(mission);try{localStorage.setItem('menunori-completed',JSON.stringify([...completed]))}catch{}render()};const m=missions[mission];$('result-dialog').innerHTML=`<button class="close" data-close aria-label="${t('Close','닫기')}">×</button><p class="eyebrow">${pass?t('NICELY ORDERED!','주문 성공!'):t('A QUICK SECOND LOOK','한 번 더 확인해요')}</p><h2 id="result-title">${pass?t('You’ve got this.','잘 주문했어요.'):t('Almost there.','거의 다 왔어요.')}</h2><p>${pass?t('Your practice order matches the mission. Take these words with you.','미션에 맞게 주문했어요. 이 표현을 기억해 보세요.'):t('A real kiosk may not catch these mistakes. Here, you get another try.','실제 키오스크는 이런 실수를 알려주지 않을 수 있어요. 여기서는 다시 해 볼 수 있어요.')}</p><ul class="checks">${checks.map(x=>`<li class="${x.ok?'':'fail'}">${x.ok?'✓':'○'} ${x.text}</li>`).join('')}</ul>${receipt()}<h3>${t('A phrase to take with you','직원에게 쓸 수 있는 표현')}</h3><div class="phrase"><strong>${m.phrase[0]}</strong><small>${m.phrase[1]}</small></div><p>${t('Remember: 주문 = order · 수량 = quantity · 확인 = confirm. Ordering screens and recipes vary by restaurant.','기억해요: 주문 = order · 수량 = quantity · 확인 = confirm. 식당마다 화면과 조리법은 달라요.')}</p><div class="dialog-actions"><button class="secondary" id="retry">${pass?t('Try again','다시 연습'):t('Fix my order','주문 수정')}</button>${pass?`<button class="primary" id="next">${mission===4?t('Back to mission 1','첫 미션으로'):t('Next mission','다음 미션')}</button>`:''}</div>`;$('retry').onclick=()=>{$('result-dialog').close();if(pass)startMission(mission)};if(pass)$('next').onclick=()=>{$('result-dialog').close();startMission((mission+1)%5)};$('result-dialog').showModal()}
$('dine').onclick=()=>{mode='dine';renderCart()};$('takeaway').onclick=()=>{mode='takeaway';renderCart()};$('menu-grid').onclick=e=>{const b=e.target.closest('[data-food]');if(b)showFood(b.dataset.food)};$('mission-tabs').onclick=e=>{const b=e.target.closest('[data-mission]');if(!b)return;const i=+b.dataset.mission;if(i===mission)return;if(cart.length&&!confirm(t('Start this mission with a fresh basket?','장바구니를 비우고 새 미션을 시작할까요?')))return;startMission(i)};$('cart-items').onclick=e=>{const q=e.target.closest('[data-qty]'),r=e.target.closest('[data-remove]');if(q){const x=cart.find(x=>x.key===+q.dataset.qty);if(x){x.qty=Math.min(9,x.qty+ +q.dataset.change);cart=cart.filter(x=>x.qty>0)}}if(r)cart=cart.filter(x=>x.key!==+r.dataset.remove);renderCart()};$('review').onclick=review;document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target.closest('[data-close]'))d.close()})});
const query=new URLSearchParams(location.search);const requested=Number(query.get('mission'));if(Number.isInteger(requested)&&requested>=1&&requested<=5)startMission(requested-1);else render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_practice_order',description:'Read the current mission, basket, options and total without changing the order.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mission:mission+1,goal:missions[mission].goal[lang],mode,items:cart.map(x=>({...x})),total:total()})});register({name:'configure_practice_order',description:'Stage a fictional practice order in the visible basket. Does not submit the order.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['dine','takeaway']},items:{type:'array',items:{type:'object',properties:{id:{type:'string',enum:menu.map(x=>x.id)},qty:{type:'integer',minimum:1,maximum:9},spice:{type:'string',enum:['normal','mild']},extra:{type:'boolean'}},required:['id','qty'],additionalProperties:false}}},required:['mode','items'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!['dine','takeaway'].includes(input.mode)||!Array.isArray(input.items))throw Error('Invalid order');const backup=cart;const oldMode=mode;try{cart=[];for(const x of input.items)addItem(x.id,x.qty,x.spice||'normal',x.extra??false);mode=input.mode;renderCart();return{mode,items:cart,total:total()}}catch(e){cart=backup;mode=oldMode;renderCart();throw e}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
